use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
# [test] fn matrix_iter () { let mut matrix : BitMatrix < usize , usize > = BitMatrix :: new (64 , 100) ; matrix . insert (3 , 22) ; matrix . insert (3 , 75) ; matrix . insert (2 , 99) ; matrix . insert (4 , 0) ; matrix . union_rows (3 , 5) ; matrix . insert_all_into_row (6) ; let expected = [99] ; let mut iter = expected . iter () ; for i in matrix . iter (2) { let j = * iter . next () . unwrap () ; assert_eq ! (i , j) ; } assert ! (iter . next () . is_none ()) ; let expected = [22 , 75] ; let mut iter = expected . iter () ; assert_eq ! (matrix . count (3) , expected . len ()) ; for i in matrix . iter (3) { let j = * iter . next () . unwrap () ; assert_eq ! (i , j) ; } assert ! (iter . next () . is_none ()) ; let expected = [0] ; let mut iter = expected . iter () ; assert_eq ! (matrix . count (4) , expected . len ()) ; for i in matrix . iter (4) { let j = * iter . next () . unwrap () ; assert_eq ! (i , j) ; } assert ! (iter . next () . is_none ()) ; let expected = [22 , 75] ; let mut iter = expected . iter () ; assert_eq ! (matrix . count (5) , expected . len ()) ; for i in matrix . iter (5) { let j = * iter . next () . unwrap () ; assert_eq ! (i , j) ; } assert ! (iter . next () . is_none ()) ; assert_eq ! (matrix . count (6) , 100) ; let mut count = 0 ; for (idx , i) in matrix . iter (6) . enumerate () { assert_eq ! (idx , i) ; count += 1 ; } assert_eq ! (count , 100) ; if let Some (i) = matrix . iter (7) . next () { panic ! ("expected no elements in row, but contains element {:?}" , i) ; } }
}